def get_survey(sid):
    row = database.execute("SELECT id, title, description FROM surveys WHERE id=?", (sid,)).fetchone()
    if not row: return None
    qrows = database.execute("SELECT id, position, type, title, required FROM questions WHERE survey_id=? ORDER BY position", (sid,)).fetchall()
    questions = []
    for qid, pos, qtype, qtitle, required in qrows:
        q = {"type": qtype, "title": qtitle, "required": bool(required)}
        if qtype == "single_choice":
            orows = database.execute("SELECT value FROM options WHERE question_id=? ORDER BY position", (qid,)).fetchall()
            q["options"] = [r[0] for r in orows]
        questions.append(q)
    return {"id": sid, "title": row[1], "description": row[2], "questions": questions}
```

