```python
def validate_survey(payload):
    errors = []
    if not isinstance(payload, dict):
        return ["body must be a JSON object"]
    title = payload.get("title")
    if not isinstance(title, str):
        errors.append("title must be a string")
    elif not title.strip():
        errors.append("title must not be empty")
    description = payload.get("description", "")
    if not isinstance(description, str):
        errors.append("description must be a string")
    questions = payload.get("questions")
    if not isinstance(questions, list):
        errors.append("questions must be an array")
        return errors  # can't iterate
    if len(questions) == 0:
        errors.append("questions must contain at least one question")
    for i, q in enumerate(questions):
        path = f"questions[{i}]"
        if not isinstance(q, dict):
            errors.append(f"{path} must be an object")
            continue
        qtype = q.get("type")
        if qtype not in ("text", "single_choice"):
            errors.append(f"{path}.type must be \"text\" or \"single_choice\"")
        qtitle = q.get("title")
        if not isinstance(qtitle, str):
            errors.append(f"{path}.title must be a string")
        elif not qtitle.strip():
            errors.append(f"{path}.title must not be empty")
        required = q.get("required", False)
        if not isinstance(required, bool):
            errors.append(f"{path}.required must be a boolean")
        if qtype == "text":
            if "options" in q and q["options"]:
                errors.append(f"{path} text question must not have options")
        elif qtype == "single_choice":
            options = q.get("options")
            if not isinstance(options, list):
                errors.append(f"{path}.options must be an array")
                continue
            if len(options) < 2:
                errors.append(f"{path}.options must have at least 2 options")
            seen = set()
            for j, opt in enumerate(options):
                opath = f"{path}.options[{j}]"
                if not isinstance(opt, str):
                    errors.append(f"{opath} must be a string")
                    continue
                stripped = opt.strip()
                if not stripped:
                    errors.append(f"{opath} must not be empty")
                elif stripped in seen:
                    errors.append(f"{opath} duplicates another option in this question")
                else:
                    seen.add(stripped)
    return errors
```

