```python
def get_survey(sid):
    row = database.execute("SELECT id, title, COALESCE(description, '') FROM surveys WHERE id = ?", (sid,)).fetchone()
    if row is None:
        return None
    qrows = database.execute("SELECT id, type, title, required FROM questions WHERE survey_id = ? ORDER BY position, id", (sid,)).fetchall()
    questions = []
    for qid, qtype, qtitle, required in qrows:
        item = {"type": qtype, "title": qtitle, "required": bool(required)}
        if qtype == "single_choice":
            item["options"] = [r[0] for r in database.execute("SELECT value FROM options WHERE question_id = ? ORDER BY position, id", (qid,))]
        questions.append(item)
    return {"id": row[0], "title": row[1], "description": row[2], "questions": questions}
```

