def create_survey(payload):
    title = payload["title"].strip()
    description = payload.get("description", "")
    if description is None: description = ""  # validation ensures str
    cur = database.execute("INSERT INTO surveys (title, description) VALUES (?, ?)", (title, description))
    sid = cur.lastrowid
    for i, q in enumerate(payload["questions"]):
        qtitle = q["title"].strip()
        qtype = q["type"]
        required = bool(q.get("required", False))
