                                (sid, i, qtype, qtitle, required))
        qid = cur.lastrowid
        if qtype == "single_choice":
            for j, opt in enumerate(q["options"]):
                database.execute("INSERT INTO options (question_id, position, value) VALUES (?, ?, ?)", (qid, j, opt.strip()))
    database.commit()
    return get_survey(sid)
