    description = payload.get("description", "")
    if not isinstance(description, str):
        errors.append("description 必须是字符串")
    questions = payload.get("questions")
    if not isinstance(questions, list):
        errors.append("questions 必须是数组")
        return errors
    if len(questions) == 0:
        errors.append("questions 至少需要一道题")
    for i, q in enumerate(questions):
        path = f"questions[{i}]"
        if not isinstance(q, dict):
            errors.append(f"{path} 必须是对象")
            continue
        qtype = q.get("type")
        if qtype not in ("text", "single_choice"):
            errors.append(f"{path}.type 必须是 text 或 single_choice")
        qtitle = q.get("title")
        if not isinstance(qtitle, str):
            errors.append(f"{path}.title 必须是字符串")
        elif not qtitle.strip():
            errors.append(f"{path}.title 去掉首尾空白后不能为空")
        if "required" in q and not isinstance(q["required"], bool):
            errors.append(f"{path}.required 必须是布尔值")
        if qtype == "text":
            if "options" in q and q["options"]:
                errors.append(f"{path} 是文本题，不能包含选项")
        elif qtype == "single_choice":
            options = q.get("options")
            if not isinstance(options, list):
                errors.append(f"{path}.options 必须是字符串数组")
                continue
            if len(options) < 2:
                errors.append(f"{path}.options 至少需要两个选项")
            seen = set()
            for j, opt in enumerate(options):
                opath = f"{path}.options[{j}]"
                if not isinstance(opt, str):
                    errors.append(f"{opath} 必须是字符串")
                    continue
                stripped = opt.strip()
                if not stripped:
                    errors.append(f"{opath} 去掉首尾空白后不能为空")
                elif stripped in seen:
                    errors.append(f"{opath} 与其他选项重复")
                else:
                    seen.add(stripped)
    return errors
